/// One integration by a reference code: the problem, `rtol = atol`, the accepted and
/// rejected steps, the evaluations of the right-hand side and the state at `t1`.
pub struct Run {
    pub problem: Problem,
    pub tol: f64,
    pub steps: usize,
    pub rejected: usize,
    pub nfev: usize,
    pub y: &'static [f64],
}

